import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { lineTotal } from '../src/pricing.js';
import { applyCoupon, cartTotal } from '../src/cart.js';
const coupons = JSON.parse(readFileSync(new URL('../data/coupons.json', import.meta.url), 'utf8'));
const items = [{ name: 'a', price: 40, qty: 2 }, { name: 'b', price: 10, qty: 1, discount: 10 }]; // 89
test('discount is a percentage', () => {
  assert.equal(lineTotal({ price: 20, qty: 2, discount: 25 }), 30);
  assert.equal(lineTotal({ price: 9.99, qty: 3 }), 29.97);
  assert.equal(lineTotal({ price: 100, qty: 1, discount: 100 }), 0);
});
test('cart total', () => assert.equal(cartTotal(items), 89));
test('percent coupon', () => assert.equal(applyCoupon(items, 'SAVE10', coupons), 80.1));
test('fixed coupon', () => assert.equal(applyCoupon(items, 'TENOFF', coupons), 79));
test('minimum not met', () => assert.throws(() => applyCoupon(items, 'BIG50', coupons), /invalid coupon/));
test('big cart qualifies', () => assert.equal(applyCoupon([{ name: 'x', price: 250, qty: 1 }], 'BIG50', coupons), 125));
test('unknown code', () => assert.throws(() => applyCoupon(items, 'NOPE', coupons), /invalid coupon/));
test('never below zero', () => assert.equal(applyCoupon([{ name: 'x', price: 30, qty: 1 }], 'TENOFF', [{ code: 'TENOFF', type: 'fixed', value: 50, min: 0 }]), 0));

