// Each item: { name, price, qty, discount } where discount is a percentage off (0-100)
export function lineTotal(item) {
  const discount = item.discount ?? 0;
  return round(item.price * (1 - discount / 100) * item.qty);
}

export function round(x) {
  return Math.round(x * 100) / 100;
}

solution.src/cart.js:
import { lineTotal, round } from './pricing.js';

export function cartTotal(items) {
  return round(items.reduce((sum, item) => sum + lineTotal(item), 0));
}

export function applyCoupon(items, code, coupons) {
  const total = cartTotal(items);
  const c = coupons.find((x) => x.code === code);
  if (!c || total < c.min) throw new Error('invalid coupon');
  const after = c.type === 'percent' ? total * (1 - c.value / 100) : total - c.value;
  return Math.max(0, round(after));
}
